export function getProblemBySlug(slug: string): GeneratedProblem | undefined {
  return generatedProblems.find((p) => p.slug === slug);
}

/** Legacy ids (v3-12, ...) still resolve, so older links keep working. */
export function getProblemByAnyId(id: string): GeneratedProblem | undefined {
  return generatedProblems.find((p) => p.slug === id || p.legacyIds.includes(id));
}
